58	// ========== RawNewsItemSchema ==========
59	
60	export const RawNewsItemSchema = z.object({
61	  id: z.string().min(1, "ID must not be empty"),
62	  title: z.string().min(1, "Title must not be empty"),
63	  content: z.string().min(50, "Content must be at least 50 characters long"),
64	  source: RawNewsSourceSchema,
