69	// ========== StructuredInsightItemSchema ==========
70	
71	export const StructuredInsightItemSchema = z.object({
72	  id: z.string().min(1, "ID must not be empty"),
73	  ingested_at: z.string().datetime({ message: "ingested_at must be a valid ISO 8601 datetime" }),
74	  source: RawNewsSourceSchema,
75	  title: z.string().min(1, "Title must not be empty"),
76	  title_zh: z.string().nullable(),
77	  abstract: z.string().min(1, "Abstract must not be empty").max(120, "Abstract must be 120 characters or fewer"),
78	  entities: EntitiesSchema,
79	  topics: z.array(TopicSchema).min(1, "At least one topic is required"),
80	  category: z.object({
81	    primary: z.string().min(1, "Primary category must not be empty"),
82	    secondary: z.string().nullable(),
83	    confidence: z.number().min(0, "Confidence must be >= 0").max(1, "Confidence must be <= 1"),
84	  }),
85	  sentiment: SentimentSchema,
86	  risk_level: RiskLevelSchema,
87	  risk_rationale: z.string().nullable(),
88	  impact: ImpactSchema,
89	  extraction_confidence: z.number().min(0, "Extraction confidence must be >= 0").max(1, "Extraction confidence must be <= 1"),
90	  needs_review: z.boolean(),
91	  review_reason: z.string().nullable(),
92	}).superRefine((data, ctx) => {
93	  // At least one of entities sub-arrays must be non-empty, unless topics has entries
94	  const hasAnyEntity = data.entities.companies.length > 0
95	    || data.entities.products.length > 0
96	    || data.entities.people.length > 0
97	    || data.entities.technologies.length > 0;
98	  if (!hasAnyEntity && data.topics.length === 0) {
