1	/**
2	 * Logger — 分级日志工具
3	 *
4	 * Provides 5 log levels (DEBUG, INFO, WARN, ERROR, FATAL) with
5	 * global level control, stdout/stderr routing, and structured data support.
6	 */
7	
8	/**
9	 * Log levels ordered by severity (lower number = more verbose).
10	 */
11	export enum LogLevel {
12	  DEBUG = 0,
13	  INFO = 1,
14	  WARN = 2,
15	  ERROR = 3,
16	  FATAL = 4,
17	}
18	
19	/**
20	 * Represents a single structured log entry.
21	 */
22	export interface LogEntry {
23	  timestamp: string;
24	  level: LogLevel;
25	  module: string;
26	  message: string;
27	  data?: Record<string, unknown>;
28	}
29	
30	/**
31	 * Optional configuration for Logger constructor.
32	 */
33	export interface LoggerOptions {
34	  // Reserved for future options (e.g., custom output stream, formatting)
35	}
36	
37	/**
38	 * Mapping from LogLevel enum to display name strings.
39	 */
40	const LEVEL_NAMES: Record<LogLevel, string> = {
41	  [LogLevel.DEBUG]: 'DEBUG',
42	  [LogLevel.INFO]: 'INFO',
43	  [LogLevel.WARN]: 'WARN',
44	  [LogLevel.ERROR]: 'ERROR',
45	  [LogLevel.FATAL]: 'FATAL',
46	};
47	
48	/**
49	 * Parse a log level string from environment variable or config.
50	 * Returns null for invalid / unrecognized values.
51	 */
52	function parseLogLevel(value: string | undefined): LogLevel | null {
53	  if (!value) return null;
54	  const upper = value.toUpperCase().trim();
55	  for (const [key, val] of Object.entries(LogLevel)) {
56	    if (typeof val === 'number' && key === upper) {
57	      return val as LogLevel;
58	    }
59	  }
60	  return null;
61	}
62	
63	/**
64	 * Current global log level. All log entries below this threshold are suppressed.
65	 * Initialized from the LOG_LEVEL environment variable, defaulting to INFO.
66	 */
67	let globalLevel: LogLevel =
68	  parseLogLevel(
69	    typeof process !== 'undefined' ? process.env.LOG_LEVEL : undefined,
70	  ) ?? LogLevel.INFO;
71	
72	/**
73	 * Generate an ISO 8601 timestamp (UTC).
74	 */
75	function formatTimestamp(): string {
76	  return new Date().toISOString();
77	}
78	
79	/**
80	 * Logger — a lightweight structured logger with global level control.
81	 *
82	 * @example
83	 *   const log = new Logger('INGEST');
84	 *   log.info('Document received', { docId: 42 });
85	 *   log.error('Processing failed', { error: err.message });
86	 */
87	export class Logger {
88	  private readonly moduleName: string;
89	
90	  /**
91	   * Create a new Logger instance bound to the given module name.
92	   *
93	   * @param module  Module identifier (e.g. "INGEST", "EXTRACT", "PIPELINE")
94	   * @param _options  Optional logger configuration (reserved)
95	   */
96	  constructor(module: string, _options?: LoggerOptions) {
97	    this.moduleName = module;
98	  }
99	
100	  // ─── Instance methods ────────────────────────────────────────
101	
102	  /** Log a DEBUG message (lowest severity). */
103	  debug(message: string, data?: Record<string, unknown>): void {
104	    this.log(LogLevel.DEBUG, message, data);
105	  }
106	
107	  /** Log an INFO message. */
108	  info(message: string, data?: Record<string, unknown>): void {
109	    this.log(LogLevel.INFO, message, data);
110	  }
111	
112	  /** Log a WARN message. */
113	  warn(message: string, data?: Record<string, unknown>): void {
114	    this.log(LogLevel.WARN, message, data);
115	  }
116	
117	  /** Log an ERROR message (routed to stderr). */
118	  error(message: string, data?: Record<string, unknown>): void {
119	    this.log(LogLevel.ERROR, message, data);
120	  }
121	
122	  /** Log a FATAL message (routed to stderr, highest severity). */
123	  fatal(message: string, data?: Record<string, unknown>): void {
124	    this.log(LogLevel.FATAL, message, data);
125	  }
126	
127	  // ─── Static methods ──────────────────────────────────────────
128	
129	  /**
130	   * Override the global log level at runtime.
131	   * All loggers share this threshold.
132	   */
133	  static setGlobalLevel(level: LogLevel): void {
134	    globalLevel = level;
135	  }
136	
137	  /**
138	   * Read the current global log level.
139	   */
140	  static getGlobalLevel(): LogLevel {
141	    return globalLevel;
142	  }
143	
144	  // ─── Private helpers ─────────────────────────────────────────
145	
146	  /**
147	   * Core log method: filters by global level, formats the message,
148	   * and writes to stdout or stderr.
149	   */
150	  private log(level: LogLevel, message: string, data?: Record<string, unknown>): void {
151	    // Skip messages below the global threshold
152	    if (level < globalLevel) {
153	      return;
154	    }
155	
156	    const timestamp = formatTimestamp();
157	    const levelName = LEVEL_NAMES[level];
158	    let output = `[${timestamp}] [${levelName}] [${this.moduleName}] ${message}`;
159	
160	    // Append structured data as JSON when provided
161	    if (data !== undefined) {
162	      output += ` ${JSON.stringify(data)}`;
163	    }
164	
165	    output += '\n';
166	
167	    // Route ERROR and FATAL to stderr, everything else to stdout
168	    if (level >= LogLevel.ERROR) {
169	      process.stderr.write(output);
170	    } else {
171	      process.stdout.write(output);
172	    }
173	  }
174	}
